    height = observation.get('height', 0)
    position = observation.get('position', (0, 0))
    targets = observation.get('resources', [])  # For resource collection
    opponents = observation.get('opponents', [])  # For pursuit/evasion
    territory = observation.get('territory', [])  # For territory control

