    x, y = position

    # Helper to check if a cell is within bounds
    def in_bounds(nx, ny):
        return 0 <= nx < width and 0 <= ny < height

    # Helper to check if a cell is empty or traversable
    def cell_is_free(nx, ny):
        if not in_bounds(nx, ny):
            return False
        idx = ny * width + nx
        cell_value = grid[idx] if idx < len(grid) else None
        # Assuming 0 means free, others may be obstacles
        return cell_value == 0

    # Prioritize resource collection if resources are nearby
    if targets:
        # Find closest resource
        closest_target = None
        min_dist = float('inf')
