    # Else, for pursuit and evasion
    if opponents:
        # Find nearest opponent
        opponent_positions = opponents
        closest_opponent = None
        min_dist = float('inf')
        for ox, oy in opponent_positions:
            dist = abs(ox - x) + abs(oy - y)
            if dist < min_dist:
