            elif ox < x:
                dx = -1
            if oy > y:
                dy = 1
            elif oy < y:
                dy = -1
            # Try to move closer if the cell is free
            if cell_is_free(x + dx, y):
                return [dx, 0]
            elif cell_is_free(x, y + dy):
                return [0, dy]
            else:
                # Try to move diagonally if possible
                if cell_is_free(x + dx, y + dy):
                    return [dx, dy]
                # Else, try a random safe move (simple fallback)
                for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    if cell_is_free(x + ddx, y + ddy):
                        return [ddx, ddy]

    # Territory control: move towards center or expansion point
    # For robustness, move towards the center of the grid
    center_x, center_y = width // 2, height // 2
    dx = dy = 0
    if x < center_x:
        dx = 1
    elif x > center_x:
        dx = -1
    if y < center_y:
        dy = 1
    elif y > center_y:
        dy = -1
    if cell_is_free(x + dx, y):
        return [dx, 0]
    elif cell_is_free(x, y + dy):
